func (s *contentNodeShifter) Insert(old, new contentNodeI) contentNodeI {
	switch vv := old.(type) {
	case *pageState:
		newp, ok := new.(*pageState)
		if !ok {
			panic(fmt.Sprintf("unknown type %T", new))
		}
		oldSite := vv.s
		newSite := newp.s
		oldLang := oldSite.languagei
		newLang := newSite.languagei
		if oldLang == newLang {
			return new
		}
		is := make(contentNodeIs, s.numLanguages)
		is[newLang] = new
		is[oldLang] = old
		return is
	case contentNodeIs:
		newp, ok := new.(*pageState)
		if !ok {
			panic(fmt.Sprintf("unknown type %T", new))
		}
		newSite := newp.s
		newLang := newSite.languagei
		existing := vv[newLang]
		existingNil := existing == nil
		if !existingNil {
			existingVal := reflect.ValueOf(existing)
			switch existingVal.Kind() {
			case reflect.Chan, reflect.Func, reflect.Interface, reflect.Map, reflect.Ptr, reflect.Slice:
				if existingVal.IsNil() {
					existingNil = true
				}
			}
		}
		if !existingNil {
			if marker, ok := existing.(resource.StaleMarker); ok {
				marker.MarkStale()
			}
		}
		vv[newLang] = new
		return vv
	case *resourceSource:
		newp, ok := new.(*resourceSource)
		if !ok {
			panic(fmt.Sprintf("unknown type %T", new))
		}
		oldLang := 0
		if vv.r != nil {
			if _, isPage := vv.r.(page.Page); isPage {
				oldPage := vv.r.(*pageState)
				oldSite := oldPage.s
				oldLang = oldSite.languagei
