			}
		} else {
			var newMeta *hugofs.FileMeta
			newMeta = newp.fi.Meta()
			newLang = newMeta.LangIndex
		}
		if oldLang == newLang {
			return new
		}
		rs := make(resourceSources, s.numLanguages)
		rs[newLang] = newp
		rs[oldLang] = vv
		return rs
	case resourceSources:
		newp, ok := new.(*resourceSource)
		if !ok {
			panic(fmt.Sprintf("unknown type %T", new))
		}
		if newp.r != nil {
			newLang := 0
			if _, isPage := newp.r.(page.Page); isPage {
				newPage := newp.r.(*pageState)
				newSite := newPage.s
				newLang = newSite.languagei
			} else {
				var newMeta *hugofs.FileMeta
				newMeta = newp.fi.Meta()
				newLang = newMeta.LangIndex
			}
			existing := vv[newLang]
			existingNil := existing == nil
			if !existingNil {
				if types.IsNil(existing) {
					existingNil = true
				} else {
					inner := existing.r
					innerNil := inner == nil
					if !innerNil {
						if types.IsNil(inner) {
							innerNil = true
						} else if marker, ok := inner.(resource.StaleMarker); ok {
							marker.MarkStale()
						}
					}
				}
			}
			vv[newLang] = newp
			return vv
		}
		var newMeta *hugofs.FileMeta
		newMeta = newp.fi.Meta()
		newLang := newMeta.LangIndex
		existing := vv[newLang]
